diff --git a/shape/contract.go b/shape/contract.go
index 7eabb37..18f6add 100644
--- a/shape/contract.go
+++ b/shape/contract.go
@@ -327,6 +327,9 @@ func (e contractEvidence) evidenced(f contractFinding) bool {
 	if f.contract.path == "<request>" {
 		return containsNormalized(e.request, f.contract.quote)
 	}
+	if f.contract.path == f.expectation.path {
+		return false
+	}
 	if text, ok := e.expectations[f.contract.path]; ok {
 		return containsNormalized(text, f.contract.quote)
 	}

